  timestamp: string;
  type: 
    | 'RATE_LIMIT_BLOCKED'
    | 'PAYMENT_RATE_LIMIT_BLOCKED'
    | 'EDGE_RATE_LIMIT_CHALLENGE'
    | 'BYPASS_BLOCKED' 
    | 'STORAGE_TAMPERING_PURGED' 
