import ClientHistoryTimeline from "../../components/loyalty/ClientHistoryTimeline";
import { validateSchema, SCHEMAS } from "../../utils/inputValidator";
import {
  Users,
  ArrowLeft,
  Star,
  Scissors,
  Bell,
  FileText,
  Calendar,
  Smartphone,
  Lightbulb,
} from "lucide-react";

