  const [isNewClientModalOpen, setIsNewClientModalOpen] = useState(false);
  const [newClientForm, setNewClientForm] = useState({
    name: "",
    phone: "",
    cpf: "",
    birthDate: "",
    frequencyDays: "18", // Padrão 18 dias
    notes: "",
  });
  const [formErrors, setFormErrors] = useState({});

