        environment: resolved.environment,
        method: "POST",
        endpoint: "/v1/payments",
        statusCode: 403,
        statusText: "Forbidden",
        latencyMs: Math.round(performance.now() - startTime),
        requestPayload: input,
        responsePayload: { error: errorMsg },
