      let responseStatusCode = 0;
      let responseJson: any = null;

      const mockReq: any = {
        cookies: {
          [REFRESH_COOKIE_NAME]: validRefreshToken,
        },
        headers: {},
      };

      const mockRes: any = {
        status(code: number) {
          responseStatusCode = code;
          return this;
        },
        json(data: any) {
          responseJson = data;
          return this;
        },
      };

      await refreshTokenController(mockReq, mockRes);

