      expect(preserved).toBeDefined();
      expect(preserved?.is_anonymized).toBe(true);
      expect(preserved?.name).toMatch(/^TITULAR_ANONIMIZADO_/);
      expect(preserved?.cpf).toMatch(/^HASH-CPF-/);
