      const clients = getInMemoryClients();
      const inGrace = clients.find((c) => c.id === "cli_soft_deleted_active_grace");
      expect(inGrace).toBeDefined();
      expect(inGrace?.deleted_at).not.toBeNull();
      expect(inGrace?.is_anonymized).toBe(false);
